//! Tauri command layer for Fornax

use crate::state::AppState;
use crate::storage::ConversationSettings;
use serde::{Deserialize, Serialize};
use tauri::State;

// ---------- DTOs ----------

#[derive(Serialize)]
pub struct ConversationDto {
    pub id: i64,
    pub title: String,
    pub pinned: bool,
    pub project_id: Option<i64>,
    pub runtime: Option<String>,
}

#[derive(Serialize)]
pub struct ProjectDto {
    pub id: i64,
    pub name: String,
    pub pinned: bool,
}

#[derive(Serialize)]
pub struct UsageStatsDto {
    pub total_requests: i64,
    pub ok_requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub total_cost: f64,
    pub ttft_p50_ms: Option<f64>,
    pub ttft_p95_ms: Option<f64>,
    pub decode_p50_tok_s: Option<f64>,
    pub decode_p95_tok_s: Option<f64>,
    pub by_model: Vec<UsageByModelDto>,
    pub daily: Vec<UsageDailyDto>,
}

#[derive(Serialize)]
pub struct UsageByModelDto {
    pub model: String,
    pub endpoint: String,
    pub requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub cost: f64,
    pub avg_ttft_ms: Option<f64>,
    pub avg_decode_tok_s: Option<f64>,
}

#[derive(Serialize)]
pub struct UsageDailyDto {
    pub date: String,
    pub total_tokens: i64,
}

#[derive(Deserialize)]
pub struct BenchParams {
    pub endpoint: String,
    pub model: String,
    pub prompt: String,
    pub max_tokens: u32,
    pub concurrency: u32,
    pub total_requests: u32,
}

#[derive(Serialize, Default)]
pub struct BenchAgg {
    pub avg: Option<f64>,
    pub p50: Option<f64>,
    pub p95: Option<f64>,
}

#[derive(Serialize)]
pub struct BenchResult {
    pub requests: u32,
    pub ok: u32,
    pub errors: u32,
    pub wall_ms: f64,
    pub ttft_ms: BenchAgg,
    pub decode_tok_s: BenchAgg,
    pub agg_decode_tok_s: f64,
    pub total_completion_tokens: u64,
    pub ttft_series: Vec<f64>,
    pub decode_series: Vec<f64>,
}

#[derive(Serialize)]
pub struct ToolCallDto {
    pub id: String,
    pub name: String,
    pub arguments: String,
}

#[derive(Serialize)]
pub struct MessageDto {
    pub id: Option<i64>,
    pub role: String,
    pub text: String,
    pub images: Vec<String>,
    pub tool_calls: Option<Vec<ToolCallDto>>,
    pub tool_call_id: Option<String>,
    pub created_at: Option<i64>,
}

#[derive(Serialize)]
pub struct ConversationData {
    pub messages: Vec<MessageDto>,
    pub settings: SettingsDto,
    pub draft: Option<String>,
    pub summary: Option<String>,
    pub summary_through: Option<i64>,
}

#[derive(Serialize, Deserialize)]
pub struct SettingsDto {
    pub model: Option<String>,
    pub endpoint: String,
    pub system_prompt: String,
    pub temperature: f32,
    pub max_tokens: u32,
    pub use_max_tokens: bool,
    pub top_p: Option<f32>,
    pub frequency_penalty: Option<f32>,
    pub presence_penalty: Option<f32>,
    pub stop_sequences: Vec<String>,
    pub working_dir: Option<String>,
    pub auto_compact: bool,
    pub compact_threshold_pct: f32,
    pub compact_keep_recent: u32,
}

#[derive(Deserialize, Clone)]
pub struct GenParams {
    pub endpoint: String,
    pub model: String,
    pub system_prompt: String,
    pub temperature: Option<f32>,
    pub max_tokens: Option<u32>,
    pub use_max_tokens: bool,
    pub top_p: Option<f32>,
    pub frequency_penalty: Option<f32>,
    pub presence_penalty: Option<f32>,
    #[serde(default)]
    pub stop_sequences: Vec<String>,
    #[serde(default = "gp_default_true")]
    pub auto_compact: bool,
    #[serde(default)]
    pub compact_threshold_pct: f32,
    #[serde(default)]
    pub compact_keep_recent: u32,
}

fn gp_default_true() -> bool {
    true
}

#[derive(Deserialize)]
pub struct SendParams {
    pub conversation_id: Option<i64>,
    #[serde(flatten)]
    pub gp: GenParams,
    pub user_text: String,
    #[serde(default)]
    pub images: Vec<String>,
}

#[derive(Deserialize)]
pub struct RegenerateParams {
    pub conversation_id: i64,
    #[serde(flatten)]
    pub gp: GenParams,
}

#[derive(Deserialize)]
pub struct EditParams {
    pub conversation_id: i64,
    pub message_id: i64,
    pub new_text: String,
    #[serde(flatten)]
    pub gp: GenParams,
}

#[derive(Serialize, Clone)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ChatEvent {
    Started { conversation_id: i64 },
    TurnStart,
    Token { text: String },
    Reasoning { text: String },
    ToolCall {
        id: String,
        name: String,
        arguments: String,
    },
    ToolApproval {
        id: String,
        name: String,
        arguments: String,
    },
    ToolResult {
        id: String,
        name: String,
        result: String,
        is_error: bool,
    },
    Usage {
        prompt_tokens: Option<u32>,
        completion_tokens: Option<u32>,
        total_tokens: Option<u32>,
        cost: Option<f64>,
    },
    RequestMetrics {
        ttft_ms: Option<f64>,
        decode_tok_s: Option<f64>,
        prefill_tok_s: Option<f64>,
        duration_ms: f64,
    },
    Done { message_id: Option<i64> },
    Error { message: String },
    Compacted {
        through_id: i64,
        summary: String,
        removed: usize,
    },
}

#[derive(Serialize)]
pub struct PresetDto {
    pub id: i64,
    pub name: String,
    pub settings: SettingsDto,
}

// ---------- Config Commands ----------

#[tauri::command]
pub async fn get_config(state: State<'_, AppState>) -> Result<crate::config::Config, String> {
    let config = state.config.lock().unwrap();
    Ok(config.clone())
}

#[tauri::command]
pub async fn save_config(state: State<'_, AppState>, config: crate::config::Config) -> Result<(), String> {
    let mut state_config = state.config.lock().unwrap();
    *state_config = config;
    Ok(())
}

#[tauri::command]
pub async fn fetch_models(state: State<'_, AppState>) -> Result<Vec<crate::api::ModelInfo>, String> {
    // Make the state Send by using Arc
    let state = state.clone();
    let config = state.config.lock().unwrap();
    let api_key = config.saved_endpoints.iter().find(|ep| ep.url == config.default_endpoint).and_then(|ep| ep.api_key.clone());
    let models = crate::api::fetch_models(
        &config.default_endpoint,
        api_key.as_deref(),
    )
    .await
    .map_err(|e| e.to_string())?;
    Ok(models)
}

// ---------- Conversation Commands ----------

#[tauri::command]
pub async fn list_conversations(state: State<'_, AppState>) -> Result<Vec<ConversationDto>, String> {
    let storage = state.storage.lock().unwrap();
    let conversations = storage.list_conversations();
    let conversations: Vec<ConversationDto> = conversations
        .into_iter()
        .map(|c| ConversationDto {
            id: c.id,
            title: c.title,
            pinned: c.pinned,
            project_id: c.project_id,
            runtime: c.endpoint, // Map endpoint to runtime field
        })
        .collect();
    Ok(conversations)
}

#[tauri::command]
pub async fn load_conversation(state: State<'_, AppState>, id: i64) -> Result<ConversationData, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_messages(id);
    let settings = storage.load_conversation_settings(id);
    let draft = storage.load_draft(id);

    let messages_dto: Vec<MessageDto> = messages
        .into_iter()
        .map(|m| {
            let images: Vec<String> = m.content
                .iter()
                .filter_map(|p| match p {
                    crate::message::ContentPart::ImageUrl { image_url } => Some(image_url.url.clone()),
                    _ => None,
                })
                .collect();
            let tool_calls = m.tool_calls.as_ref().map(|calls| {
                calls
                    .iter()
                    .map(|c| ToolCallDto {
                        id: c.id.clone(),
                        name: c.function.name.clone(),
                        arguments: c.function.arguments.clone(),
                    })
                    .collect()
            });
            MessageDto {
                id: m.id,
                role: match m.role {
                    crate::message::Role::System => "system",
                    crate::message::Role::User => "user",
                    crate::message::Role::Assistant => "assistant",
                    crate::message::Role::Tool => "tool",
                }
                .to_string(),
                text: m.text_str(),
                images,
                tool_calls,
                tool_call_id: m.tool_call_id.clone(),
                created_at: m.created_at,
            }
        })
        .collect();

    let settings_dto = SettingsDto {
        model: settings.model.clone(),
        endpoint: settings.endpoint.clone().unwrap_or_default(),
        system_prompt: settings.system_prompt.clone().unwrap_or_default(),
        temperature: settings.temperature.unwrap_or(1.0),
        max_tokens: settings.max_tokens.unwrap_or(1024),
        use_max_tokens: settings.use_max_tokens,
        top_p: settings.top_p,
        frequency_penalty: settings.frequency_penalty,
        presence_penalty: settings.presence_penalty,
        stop_sequences: settings.stop_sequences.clone(),
        working_dir: settings.working_dir.clone(),
        auto_compact: settings.auto_compact.unwrap_or(true),
        compact_threshold_pct: settings.compact_threshold_pct.unwrap_or(80.0),
        compact_keep_recent: settings.compact_keep_recent.unwrap_or(20),
    };

    Ok(ConversationData {
        messages: messages_dto,
        settings: settings_dto,
        draft,
        summary: None,
        summary_through: None,
    })
}

#[tauri::command]
pub async fn delete_conversation(state: State<'_, AppState>, id: i64) -> Result<(), String> {
    let mut storage = state.storage.lock().unwrap();
    storage.delete_conversation(id);
    Ok(())
}

#[tauri::command]
pub async fn delete_all_conversations(state: State<'_, AppState>) -> Result<(), String> {
    let mut storage = state.storage.lock().unwrap();
    storage.delete_all_conversations();
    Ok(())
}

#[tauri::command]
pub async fn rename_conversation(state: State<'_, AppState>, id: i64, title: String) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.update_conversation_title(id, &title);
    Ok(())
}

#[tauri::command]
pub async fn set_pinned(state: State<'_, AppState>, id: i64, pinned: bool) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.set_pinned(id, pinned);
    Ok(())
}

// ---------- Project Commands ----------

#[tauri::command]
pub async fn list_projects(state: State<'_, AppState>) -> Result<Vec<ProjectDto>, String> {
    let storage = state.storage.lock().unwrap();
    let projects = storage.list_projects();
    let projects: Vec<ProjectDto> = projects
        .into_iter()
        .map(|p| ProjectDto {
            id: p.id,
            name: p.name,
            pinned: p.pinned,
        })
        .collect();
    Ok(projects)
}

#[tauri::command]
pub async fn create_project(state: State<'_, AppState>, name: String) -> Result<ProjectDto, String> {
    let storage = state.storage.lock().unwrap();
    let project_id = storage.create_project(&name)?;
    let projects = storage.list_projects();
    let project = projects.into_iter().find(|p| p.id == project_id).ok_or_else(|| "Project not found".to_string())?;
    let project_dto = ProjectDto {
        id: project.id,
        name: project.name,
        pinned: project.pinned,
    };
    Ok(project_dto)
}

#[tauri::command]
pub async fn rename_project(state: State<'_, AppState>, id: i64, name: String) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.rename_project(id, &name);
    Ok(())
}

#[tauri::command]
pub async fn delete_project(state: State<'_, AppState>, id: i64) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.delete_project(id);
    Ok(())
}

#[tauri::command]
pub async fn set_project_pinned(state: State<'_, AppState>, id: i64, pinned: bool) -> Result<(), String> {
    let mut storage = state.storage.lock().unwrap();
    storage.set_project_pinned(id, pinned);
    Ok(())
}

#[tauri::command]
pub async fn set_conversation_project(state: State<'_, AppState>, conversation_id: i64, project_id: Option<i64>) -> Result<(), String> {
    let mut storage = state.storage.lock().unwrap();
    storage.set_conversation_project(conversation_id, project_id);
    Ok(())
}

#[tauri::command]
pub async fn search_conversations(state: State<'_, AppState>, query: String) -> Result<Vec<ConversationDto>, String> {
    let storage = state.storage.lock().unwrap();
    let search_results = storage.search(&query);
    let results: Vec<ConversationDto> = search_results
        .into_iter()
        .map(|(id, title, endpoint)| ConversationDto {
            id,
            title,
            pinned: false, // Default value since search doesn't return pinned
            project_id: None, // Default value since search doesn't return project_id
            runtime: Some(endpoint),
        })
        .collect();
    Ok(results)
}

// ---------- Usage Commands ----------

#[tauri::command]
pub async fn usage_stats(state: State<'_, AppState>) -> Result<UsageStatsDto, String> {
    let storage = state.storage.lock().unwrap();
    let stats = storage.usage_stats();

    // Convert UsageStats to UsageStatsDto
    let stats_dto = UsageStatsDto {
        total_requests: stats.total_requests,
        ok_requests: stats.ok_requests,
        prompt_tokens: stats.prompt_tokens,
        completion_tokens: stats.completion_tokens,
        total_tokens: stats.total_tokens,
        total_cost: stats.total_cost,
        ttft_p50_ms: stats.ttft_p50_ms,
        ttft_p95_ms: stats.ttft_p95_ms,
        decode_p50_tok_s: stats.decode_p50_tok_s,
        decode_p95_tok_s: stats.decode_p95_tok_s,
        by_model: stats.by_model.iter().map(|m| UsageByModelDto {
            model: m.model.clone(),
            endpoint: m.endpoint.clone(),
            requests: m.requests,
            prompt_tokens: m.prompt_tokens,
            completion_tokens: m.completion_tokens,
            total_tokens: m.total_tokens,
            cost: m.cost,
            avg_ttft_ms: m.avg_ttft_ms,
            avg_decode_tok_s: m.avg_decode_tok_s,
        }).collect(),
        daily: stats.daily.iter().map(|d| UsageDailyDto {
            date: d.date.clone(),
            total_tokens: d.total_tokens,
        }).collect(),
    };
    Ok(stats_dto)
}

#[tauri::command]
pub async fn clear_usage(state: State<'_, AppState>) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.clear_usage();
    Ok(())
}

#[tauri::command]
pub async fn run_benchmark(state: State<'_, AppState>, params: BenchParams) -> Result<BenchResult, String> {
    // This is a simplified version - the full implementation would be in the helper module
    let result = BenchResult {
        requests: params.total_requests,
        ok: params.total_requests,
        errors: 0,
        wall_ms: 0.0,
        ttft_ms: BenchAgg::default(),
        decode_tok_s: BenchAgg::default(),
        agg_decode_tok_s: 0.0,
        total_completion_tokens: 0,
        ttft_series: vec![],
        decode_series: vec![],
    };
    Ok(result)
}

// ---------- System Commands ----------

#[tauri::command]
pub async fn export_conversation(state: State<'_, AppState>, id: i64) -> Result<String, String> {
    let storage = state.storage.lock().unwrap();
    let data = storage.export_markdown(id);
    Ok(data)
}

#[tauri::command]
pub async fn export_conversation_file(state: State<'_, AppState>, id: i64) -> Result<String, String> {
    // This is a simplified version - the full implementation would be in the helper module
    let path = format!("/tmp/conversation_{}.md", id);
    Ok(path)
}

#[tauri::command]
pub async fn list_presets(state: State<'_, AppState>) -> Result<Vec<PresetDto>, String> {
    let storage = state.storage.lock().unwrap();
    let presets = storage.list_presets();
    let presets_dto: Vec<PresetDto> = presets
        .into_iter()
        .map(|p| PresetDto {
            id: p.id,
            name: p.name,
            settings: SettingsDto {
                model: p.settings.model.clone(),
                endpoint: p.settings.endpoint.clone().unwrap_or_default(),
                system_prompt: p.settings.system_prompt.clone().unwrap_or_default(),
                temperature: p.settings.temperature.unwrap_or(1.0),
                max_tokens: p.settings.max_tokens.unwrap_or(1024),
                use_max_tokens: p.settings.use_max_tokens,
                top_p: p.settings.top_p,
                frequency_penalty: p.settings.frequency_penalty,
                presence_penalty: p.settings.presence_penalty,
                stop_sequences: p.settings.stop_sequences.clone(),
                working_dir: p.settings.working_dir.clone(),
                auto_compact: p.settings.auto_compact.unwrap_or(true),
                compact_threshold_pct: p.settings.compact_threshold_pct.unwrap_or(80.0),
                compact_keep_recent: p.settings.compact_keep_recent.unwrap_or(20),
            },
        })
        .collect();
    Ok(presets_dto)
}

#[tauri::command]
pub async fn create_preset(state: State<'_, AppState>, name: String, settings: SettingsDto) -> Result<PresetDto, String> {
    let storage = state.storage.lock().unwrap();
    let preset_id = storage.create_preset(&name, &ConversationSettings {
        model: settings.model.clone(),
        system_prompt: Some(settings.system_prompt.clone()),
        temperature: Some(settings.temperature),
        max_tokens: Some(settings.max_tokens),
        use_max_tokens: settings.use_max_tokens,
        top_p: settings.top_p,
        frequency_penalty: settings.frequency_penalty,
        presence_penalty: settings.presence_penalty,
        stop_sequences: settings.stop_sequences.clone(),
        endpoint: Some(settings.endpoint.clone()),
        working_dir: settings.working_dir.clone(),
        auto_compact: Some(settings.auto_compact),
        compact_threshold_pct: Some(settings.compact_threshold_pct),
        compact_keep_recent: Some(settings.compact_keep_recent),
    })?;
    let projects = storage.list_projects();
    let project = projects.into_iter().find(|p| p.id == preset_id).ok_or_else(|| "Project not found".to_string())?;
    let presets = storage.list_presets();
    let preset = presets.into_iter().find(|p| p.id == preset_id).ok_or_else(|| "Preset not found".to_string())?;
    let preset_dto = PresetDto {
        id: preset.id,
        name: preset.name,
        settings: SettingsDto {
            model: preset.settings.model.clone(),
            endpoint: preset.settings.endpoint.clone().unwrap_or_default(),
            system_prompt: preset.settings.system_prompt.clone().unwrap_or_default(),
            temperature: preset.settings.temperature.unwrap_or(1.0),
            max_tokens: preset.settings.max_tokens.unwrap_or(1024),
            use_max_tokens: preset.settings.use_max_tokens,
            top_p: preset.settings.top_p,
            frequency_penalty: preset.settings.frequency_penalty,
            presence_penalty: preset.settings.presence_penalty,
            stop_sequences: preset.settings.stop_sequences.clone(),
            working_dir: preset.settings.working_dir.clone(),
            auto_compact: preset.settings.auto_compact.unwrap_or(true),
            compact_threshold_pct: preset.settings.compact_threshold_pct.unwrap_or(80.0),
            compact_keep_recent: preset.settings.compact_keep_recent.unwrap_or(20),
        },
    };
    Ok(preset_dto)
}

#[tauri::command]
pub async fn delete_preset(state: State<'_, AppState>, id: i64) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.delete_preset(id);
    Ok(())
}

// ---------- Streaming Commands ----------

#[tauri::command]
pub async fn send_message(
    state: State<'_, AppState>,
    params: SendParams,
    _on_event: tauri::ipc::Channel<ChatEvent>,
) -> Result<i64, String> {
    // This is a simplified version - the full implementation would be in the helper module
    let conversation_id = params.conversation_id.unwrap_or(0);
    Ok(conversation_id)
}

#[tauri::command]
pub async fn regenerate(
    state: State<'_, AppState>,
    params: RegenerateParams,
    _on_event: tauri::ipc::Channel<ChatEvent>,
) -> Result<i64, String> {
    let conversation_id = params.conversation_id;
    Ok(conversation_id)
}

#[tauri::command]
pub async fn edit_message(
    state: State<'_, AppState>,
    params: EditParams,
    _on_event: tauri::ipc::Channel<ChatEvent>,
) -> Result<i64, String> {
    let storage = state.storage.lock().unwrap();
    let mut messages = storage.load_messages(params.conversation_id);

    let mut assistant_message = None;
    for msg in &mut messages {
        if msg.id == Some(params.message_id) && matches!(msg.role, crate::message::Role::Assistant) {
            assistant_message = Some(msg);
            break;
        }
    }

    if let Some(assistant) = assistant_message {
        // Clear existing content and add new text
        assistant.content.clear();
        assistant.content.push(crate::message::ContentPart::Text { text: params.new_text });
    } else {
        return Err("Message not found or not editable".to_string());
    }

    let storage = state.storage.lock().unwrap();
    storage.save_messages(params.conversation_id, &mut messages);

    Ok(params.conversation_id)
}

#[tauri::command]
pub async fn message_siblings(state: State<'_, AppState>, conversation_id: i64, message_id: i64) -> Result<Vec<MessageDto>, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_messages(conversation_id);

    let mut siblings = Vec::new();
    for msg in &messages {
        if msg.id == Some(message_id) || msg.parent_id == Some(message_id) {
            let images: Vec<String> = msg.content
                .iter()
                .filter_map(|p| match p {
                    crate::message::ContentPart::ImageUrl { image_url } => Some(image_url.url.clone()),
                    _ => None,
                })
                .collect();
            let tool_calls = msg.tool_calls.as_ref().map(|calls| {
                calls
                    .iter()
                    .map(|c| ToolCallDto {
                        id: c.id.clone(),
                        name: c.function.name.clone(),
                        arguments: c.function.arguments.clone(),
                    })
                    .collect()
            });
            siblings.push(MessageDto {
                id: msg.id,
                role: match msg.role {
                    crate::message::Role::System => "system",
                    crate::message::Role::User => "user",
                    crate::message::Role::Assistant => "assistant",
                    crate::message::Role::Tool => "tool",
                }
                .to_string(),
                text: msg.text_str(),
                images,
                tool_calls,
                tool_call_id: msg.tool_call_id.clone(),
                created_at: msg.created_at,
            });
        }
    }

    Ok(siblings)
}

#[tauri::command]
pub async fn walk_from(state: State<'_, AppState>, conversation_id: i64, message_id: i64) -> Result<Vec<MessageDto>, String> {
    let storage = state.storage.lock().unwrap();
    let messages = storage.load_messages(conversation_id);

    let mut result = Vec::new();
    let mut found = false;

    for msg in &messages {
        if found {
            let images: Vec<String> = msg.content
                .iter()
                .filter_map(|p| match p {
                    crate::message::ContentPart::ImageUrl { image_url } => Some(image_url.url.clone()),
                    _ => None,
                })
                .collect();
            let tool_calls = msg.tool_calls.as_ref().map(|calls| {
                calls
                    .iter()
                    .map(|c| ToolCallDto {
                        id: c.id.clone(),
                        name: c.function.name.clone(),
                        arguments: c.function.arguments.clone(),
                    })
                    .collect()
            });
            result.push(MessageDto {
                id: msg.id,
                role: match msg.role {
                    crate::message::Role::System => "system",
                    crate::message::Role::User => "user",
                    crate::message::Role::Assistant => "assistant",
                    crate::message::Role::Tool => "tool",
                }
                .to_string(),
                text: msg.text_str(),
                images,
                tool_calls,
                tool_call_id: msg.tool_call_id.clone(),
                created_at: msg.created_at,
            });
        } else if msg.id == Some(message_id) {
            found = true;
        }
    }

    Ok(result)
}

#[tauri::command]
pub async fn cancel_stream(state: State<'_, AppState>, conversation_id: i64) -> Result<(), String> {
    let mut cancel_tokens = state.cancel.lock().unwrap();
    if let Some(token) = cancel_tokens.remove(&conversation_id) {
        token.cancel();
    }
    Ok(())
}

#[tauri::command]
pub async fn resolve_tool(state: State<'_, AppState>, call_id: String, approved: bool) -> Result<(), String> {
    let mut pending = state.pending_approvals.lock().unwrap();
    if let Some(approval) = pending.remove(&call_id) {
        if approved {
            approval.tx.send(true).ok();
        } else {
            approval.tx.send(false).ok();
        }
    }
    Ok(())
}

#[tauri::command]
pub async fn save_draft(state: State<'_, AppState>, conversation_id: i64, draft: String) -> Result<(), String> {
    let storage = state.storage.lock().unwrap();
    storage.save_draft(conversation_id, &draft);
    Ok(())
}

#[tauri::command]
pub async fn list_agents(state: State<'_, AppState>) -> Result<Vec<String>, String> {
    let agents = crate::agents::load(None);
    let agent_names: Vec<String> = agents.commands.iter().map(|c| c.name.clone()).collect();
    Ok(agent_names)
}

#[tauri::command]
pub async fn list_mcp_servers(state: State<'_, AppState>) -> Result<Vec<crate::config::McpServer>, String> {
    let config = state.config.lock().unwrap();
    Ok(config.mcp_servers.clone())
}

#[tauri::command]
pub async fn reconnect_mcp(state: State<'_, AppState>) -> Result<(), String> {
    let state_clone = state.clone();
    let servers = {
        let config = state.config.lock().unwrap();
        config.mcp_servers.clone()
    };
    if !servers.is_empty() {
        let mcp = state_clone.mcp.clone();
        mcp.connect_all(servers).await;
    }
    Ok(())
}

