        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].id, "call_abc");
        assert_eq!(calls[0].function.name, "read_file");
        assert_eq!(loaded[2].role, Role::Tool);
        assert_eq!(loaded[2].tool_call_id.as_deref(), Some("call_abc"));
        assert!(loaded[2].text_str().contains("<file contents>"));
    }

    #[test]
    fn working_dir_round_trips_in_settings() {
        let s = mem_storage();
        let conv = s.create_conversation("wd").unwrap();
        let original = ConversationSettings {
            working_dir: Some("/Users/heath/code/Fornax".into()),
            ..ConversationSettings::default()
        };
        s.save_conversation_settings(conv, &original);
        let loaded = s.load_conversation_settings(conv);
        assert_eq!(loaded.working_dir.as_deref(), Some("/Users/heath/code/Fornax"));
    }

    #[test]
    fn walk_from_returns_subtree_active_path() {
        // user -> assistant_a -> user2_a -> assistant_a2
        //                    \-> user2_b -> assistant_b2 (newer, wins on default load)
        let s = mem_storage();
        let conv = s.create_conversation("walk").unwrap();
        let base = 1_700_000_000_000i64;
        let mut u = Message::text(Role::User, "u".into());
        u.created_at = ts(base, 0);
        let mut a = Message::text(Role::Assistant, "a".into());
        a.created_at = ts(base, 1);
        let mut msgs = vec![u, a];
        s.save_messages(conv, &mut msgs).unwrap();
        let a_id = msgs[1].id.unwrap();

        let mut u2a = Message::text(Role::User, "u2-old".into());
        u2a.parent_id = Some(a_id);
        u2a.branch_index = 0;
        u2a.created_at = ts(base, 2);
        s.save_messages(conv, &mut [u2a.clone()]).unwrap();

        let mut u2b = Message::text(Role::User, "u2-new".into());
        u2b.parent_id = Some(a_id);
        u2b.branch_index = 1;
        u2b.created_at = ts(base, 10);
        s.save_messages(conv, &mut [u2b]).unwrap();

        // Walking from a_id picks the newer u2-new branch.
        let path = s.walk_from(a_id);
        let texts: Vec<String> = path.iter().map(|m| m.text_str()).collect();
        assert_eq!(texts, vec!["a", "u2-new"]);
    }
}

// Core modules are declared at the crate root via `#[path]` so the ported
// code's existing `crate::message::…` / `crate::config::…` references keep
// working unchanged. The files physically live under `src/core/`.
#[path = "core/message.rs"]
pub mod message;
#[path = "core/api.rs"]
pub mod api;
#[path = "core/storage.rs"]
pub mod storage;
#[path = "core/config.rs"]
pub mod config;
#[path = "core/slash.rs"]
pub mod slash;
#[path = "core/markdown.rs"]
pub mod markdown;
#[path = "core/tools.rs"]
pub mod tools;
#[path = "core/agents.rs"]
pub mod agents;

mod commands;
mod mcp;
mod metrics;
mod state;

use state::AppState;
use tauri::Manager;

/// One-time move of pre-rename data from the legacy `hchat` directories to
/// `fornax`, so anyone upgrading keeps their conversations, config, and tools.
/// Runs before any path is read; no-ops once the `fornax` dirs exist.
fn migrate_legacy_dirs() {
    use std::fs;
    // config + tools live under config_dir; the SQLite db under data_dir.
    // (these are the same directory on macOS, distinct on Linux.)
    for base in [dirs::config_dir(), dirs::data_dir()].into_iter().flatten() {
        let old = base.join("hchat");
        let new = base.join("fornax");
        if new.exists() || !old.exists() {
            continue;
        }
        if fs::rename(&old, &new).is_ok() {
            // Rename the db file (+ its WAL/SHM sidecars) to match the new name.
            for ext in ["", "-wal", "-shm"] {
                let from = new.join(format!("hchat.db{ext}"));
                if from.exists() {
                    let _ = fs::rename(&from, new.join(format!("fornax.db{ext}")));
                }
            }
        }
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    migrate_legacy_dirs();
    tauri::Builder::default()
        .manage(AppState::new())
        .setup(|app| {
            // Spawn the metrics poller + macmon thread; expose the active-target
            // handle so commands can retarget it.
            let target = metrics::start(app.handle().clone());
            app.manage(metrics::MetricsHandle(target));

            // Connect MCP servers in the background.
            let state = app.state::<AppState>();

            // Enforce the usage retention window once at startup.
            let retention = state.config.lock().unwrap().usage_retention_days;
            if retention > 0 {
                state.storage.lock().unwrap().prune_usage(retention);
            }

            let mcp = state.mcp.clone();
            let servers = state.config.lock().unwrap().mcp_servers.clone();
            if !servers.is_empty() {
                tauri::async_runtime::spawn(async move {
                    mcp.connect_all(servers).await;
                });
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            commands::get_config,
            commands::save_config,
            commands::fetch_models,
            commands::list_conversations,
            commands::load_conversation,
            commands::delete_conversation,
            commands::delete_all_conversations,
            commands::rename_conversation,
            commands::set_pinned,
            commands::usage_stats,
            commands::clear_usage,
            commands::run_benchmark,
            commands::list_projects,
            commands::create_project,
            commands::rename_project,
            commands::delete_project,
            commands::set_project_pinned,
            commands::set_conversation_project,
            commands::search_conversations,
            commands::export_conversation,
            commands::export_conversation_file,
            commands::save_draft,
            commands::list_agents,
            commands::list_mcp_servers,
            commands::reconnect_mcp,
            commands::cancel_stream,
            commands::send_message,
            commands::regenerate,
            commands::edit_message,
            commands::message_siblings,
            commands::walk_from,
            commands::resolve_tool,
            commands::list_presets,
            commands::create_preset,
            commands::delete_preset,

        ])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

