    /// the rest of the session via "approve all in this conversation".
    pub auto_approved: Mutex<HashSet<(i64, String)>>,
    /// MCP client connections + discovered tools. Connected asynchronously after
    /// startup (see `lib.rs` setup).
    pub mcp: Arc<McpManager>,
}

impl AppState {
    pub fn new() -> Self {
        let config = Config::load();
        let conversation_storage = crate::core::conversation_storage::ConversationStorage::new();
        let project_storage = crate::core::project_storage::ProjectStorage::new();
        let usage_storage = crate::core::usage_storage::UsageStorage::new();
        let preset_storage = crate::core::preset_storage::PresetStorage::new();
        let agent_storage = crate::core::agent_storage::AgentStorage::new();
        // Seed the default tools on first launch; tools are then (re)loaded from
