//! Project-related commands for Fornax

use crate::state::AppState;
use serde::Serialize;
use tauri::State;

#[derive(Serialize)]
pub struct ProjectDto {
    pub id: i64,
    pub name: String,
    pub pinned: bool,
}

// ---------- Project Commands ----------

#[tauri::command]
pub async fn list_projects(state: State<'_, AppState>) -> Result<Vec<ProjectDto>, String> {
    let storage = state.conversation_storage.lock().unwrap();
    let projects = storage.list_projects();
    let projects: Vec<ProjectDto> = projects
        .into_iter()
        .map(|p| ProjectDto {
            id: p.id,
            name: p.name,
            pinned: p.pinned,
        })
        .collect();
    Ok(projects)
}

#[tauri::command]
pub async fn create_project(state: State<'_, AppState>, name: String) -> Result<ProjectDto, String> {
    let storage = state.conversation_storage.lock().unwrap();
    let project_id = storage.create_project(&name)?;
    let projects = storage.list_projects();
    let project = projects.into_iter().find(|p| p.id == project_id).ok_or_else(|| "Project not found".to_string())?;
    let project_dto = ProjectDto {
        id: project.id,
        name: project.name,
        pinned: project.pinned,
    };
    Ok(project_dto)
}

#[tauri::command]
pub async fn rename_project(state: State<'_, AppState>, id: i64, name: String) -> Result<(), String> {
    let storage = state.conversation_storage.lock().unwrap();
    storage.rename_project(id, &name);
    Ok(())
}

#[tauri::command]
pub async fn delete_project(state: State<'_, AppState>, id: i64) -> Result<(), String> {
    let storage = state.conversation_storage.lock().unwrap();
    storage.delete_project(id);
    Ok(())
}

#[tauri::command]
pub async fn set_project_pinned(state: State<'_, AppState>, id: i64, pinned: bool) -> Result<(), String> {
    let mut storage = state.conversation_storage.lock().unwrap();
    storage.set_project_pinned(id, pinned);
    Ok(())
}

#[tauri::command]
pub async fn set_conversation_project(state: State<'_, AppState>, conversation_id: i64, project_id: Option<i64>) -> Result<(), String> {
    let mut storage = state.conversation_storage.lock().unwrap();
    storage.set_conversation_project(conversation_id, project_id);
    Ok(())
}

