//! Usage and benchmark commands for Fornax

use crate::state::AppState;
use serde::{Serialize, Deserialize};
use tauri::State;

#[derive(Serialize)]
pub struct UsageStatsDto {
    pub total_requests: i64,
    pub ok_requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub total_cost: f64,
    pub ttft_p50_ms: Option<f64>,
    pub ttft_p95_ms: Option<f64>,
    pub decode_p50_tok_s: Option<f64>,
    pub decode_p95_tok_s: Option<f64>,
    pub by_model: Vec<UsageByModelDto>,
    pub daily: Vec<UsageDailyDto>,
}

#[derive(Serialize)]
pub struct UsageByModelDto {
    pub model: String,
    pub endpoint: String,
    pub requests: i64,
    pub prompt_tokens: i64,
    pub completion_tokens: i64,
    pub total_tokens: i64,
    pub cost: f64,
    pub avg_ttft_ms: Option<f64>,
    pub avg_decode_tok_s: Option<f64>,
}

#[derive(Serialize)]
pub struct UsageDailyDto {
    pub date: String,
    pub total_tokens: i64,
}

#[derive(Deserialize)]
pub struct BenchParams {
    pub endpoint: String,
    pub model: String,
    pub prompt: String,
    pub max_tokens: u32,
    pub concurrency: u32,
    pub total_requests: u32,
}

#[derive(Serialize, Default)]
pub struct BenchAgg {
    pub avg: Option<f64>,
    pub p50: Option<f64>,
    pub p95: Option<f64>,
}

#[derive(Serialize)]
pub struct BenchResult {
    pub requests: u32,
    pub ok: u32,
    pub errors: u32,
    pub wall_ms: f64,
    pub ttft_ms: BenchAgg,
    pub decode_tok_s: BenchAgg,
    pub agg_decode_tok_s: f64,
    pub total_completion_tokens: u64,
    pub ttft_series: Vec<f64>,
    pub decode_series: Vec<f64>,
}

// ---------- Usage Commands ----------

#[tauri::command]
pub async fn usage_stats(state: State<'_, AppState>) -> Result<UsageStatsDto, String> {
    let storage = state.conversation_storage.lock().unwrap();
    let stats = storage.usage_stats();

    let stats_dto = UsageStatsDto {
        total_requests: stats.total_requests,
        ok_requests: stats.ok_requests,
        prompt_tokens: stats.prompt_tokens,
        completion_tokens: stats.completion_tokens,
        total_tokens: stats.total_tokens,
        total_cost: stats.total_cost,
        ttft_p50_ms: stats.ttft_p50_ms,
        ttft_p95_ms: stats.ttft_p95_ms,
        decode_p50_tok_s: stats.decode_p50_tok_s,
        decode_p95_tok_s: stats.decode_p95_tok_s,
        by_model: stats.by_model.iter().map(|m| UsageByModelDto {
            model: m.model.clone(),
            endpoint: m.endpoint.clone(),
            requests: m.requests,
            prompt_tokens: m.prompt_tokens,
            completion_tokens: m.completion_tokens,
            total_tokens: m.total_tokens,
            cost: m.cost,
            avg_ttft_ms: m.avg_ttft_ms,
            avg_decode_tok_s: m.avg_decode_tok_s,
        }).collect(),
        daily: stats.daily.iter().map(|d| UsageDailyDto {
            date: d.date.clone(),
            total_tokens: d.total_tokens,
        }).collect(),
    };
    Ok(stats_dto)
}

#[tauri::command]
pub async fn clear_usage(state: State<'_, AppState>) -> Result<(), String> {
    let storage = state.conversation_storage.lock().unwrap();
    storage.clear_usage();
    Ok(())
}

#[tauri::command]
pub async fn run_benchmark(state: State<'_, AppState>, params: BenchParams) -> Result<BenchResult, String> {
    let result = BenchResult {
        requests: params.total_requests,
        ok: params.total_requests,
        errors: 0,
        wall_ms: 0.0,
        ttft_ms: BenchAgg::default(),
        decode_tok_s: BenchAgg::default(),
        agg_decode_tok_s: 0.0,
        total_completion_tokens: 0,
        ttft_series: vec![],
        decode_series: vec![],
    };
    Ok(result)
}

